"""Public API of the ledger service.

Every function receives an already configured ``gel.AsyncIOClient`` as its first
positional argument; all remaining arguments are keyword-only.  Monetary values are
handed in as ``decimal.Decimal`` and handed back as strings with exactly two
fractional digits.
"""

from __future__ import annotations

from decimal import Decimal, ROUND_DOWN

import gel


class LedgerError(Exception):
    """Base class of every error raised by this module."""


class UnknownAccount(LedgerError):
    """No account exists for the given code."""


class DuplicateAccount(LedgerError):
    """An account with the given code already exists."""


class InvalidAmount(LedgerError):
    """The given amount is not a usable monetary value."""


class SameAccountTransfer(LedgerError):
    """Sender and recipient are the same account."""


class InsufficientFunds(LedgerError):
    """The sender does not hold enough money."""


def _validate_amount(value: Decimal, allow_zero: bool = False) -> None:
    """Validate that a Decimal amount has at most two fractional digits and is valid."""
    if not isinstance(value, Decimal):
        raise InvalidAmount(f"Amount must be a Decimal, got {type(value).__name__}")
    # Check that the value has at most 2 decimal places
    quantized = value.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
    if quantized != value:
        raise InvalidAmount(
            f"Amount {value} cannot be represented with two fractional digits"
        )
    if not allow_zero and value <= 0:
        raise InvalidAmount(f"Amount must be positive, got {value}")
    if allow_zero and value < 0:
        raise InvalidAmount(f"Amount must not be negative, got {value}")


def _format_decimal(value: Decimal) -> str:
    """Format a Decimal as a string with exactly two fractional digits."""
    return value.quantize(Decimal("0.01")).__format__("f")


async def create_account(client, *, code: str, opening_balance: Decimal) -> dict:
    """Create an account and return ``{"id", "code", "balance"}``."""
    _validate_amount(opening_balance, allow_zero=True)

    try:
        result = await client.query_single(
            """
            with
                a := (insert Account {
                    code := <str>$code,
                    opening_balance := <decimal>$opening_balance,
                }),
            select a { id, code, balance }
            """,
            code=code,
            opening_balance=opening_balance,
        )
    except gel.errors.ConstraintViolationError:
        raise DuplicateAccount(f"Account with code '{code}' already exists")

    return {
        "id": str(result.id),
        "code": result.code,
        "balance": _format_decimal(result.balance),
    }


async def create_transfer(
    client,
    *,
    sender: str,
    recipient: str,
    amount: Decimal,
    idempotency_key: str,
) -> dict:
    """Move money and return
    ``{"id", "sender", "recipient", "amount", "idempotency_key", "created"}``.
    """
    # First, check if this idempotency key already exists (fast path)
    existing = await client.query_single(
        """
        select Transfer {
            id,
            idempotency_key,
            amount,
            sender: { code },
            recipient: { code },
            created_at,
        }
        filter .idempotency_key = <str>$key
        """,
        key=idempotency_key,
    )

    if existing is not None:
        return {
            "id": str(existing.id),
            "sender": existing.sender.code,
            "recipient": existing.recipient.code,
            "amount": _format_decimal(existing.amount),
            "idempotency_key": existing.idempotency_key,
            "created": False,
        }

    # Validate arguments in the specified order
    _validate_amount(amount, allow_zero=False)  # amount <= 0 or not 2dp → InvalidAmount

    if sender == recipient:
        raise SameAccountTransfer("Sender and recipient must be different accounts")

    # Check accounts exist and get sender balance
    accounts = await client.query(
        """
        select Account { code, balance }
        filter .code in {<str>$sender_code, <str>$recipient_code}
        """,
        sender_code=sender,
        recipient_code=recipient,
    )

    account_map = {a.code: a for a in accounts}
    if sender not in account_map:
        raise UnknownAccount(f"Unknown account: '{sender}'")
    if recipient not in account_map:
        raise UnknownAccount(f"Unknown account: '{recipient}'")

