            """
            select Transfer {
                id,
                idempotency_key,
                amount,
                sender: { code },
                recipient: { code },
                created_at,
            }
            filter .idempotency_key = <str>$key
            """,
            key=idempotency_key,
        )
        return {
            "id": str(existing.id),
            "sender": existing.sender.code,
            "recipient": existing.recipient.code,
            "amount": _format_decimal(existing.amount),
            "idempotency_key": existing.idempotency_key,
            "created": False,
        }

    return {
        "id": str(result.id),
        "sender": result.sender.code,
        "recipient": result.recipient.code,
        "amount": _format_decimal(result.amount),
        "idempotency_key": result.idempotency_key,
        "created": True,
    }


